default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\System\Currentcontrolset\Control\Lsa\Msv1_0' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('AuditReceivingNTLMTraffic', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]2)) {
    Write-Output 'Mismatch: HKLM:\System\Currentcontrolset\Control\Lsa\Msv1_0 [AuditReceivingNTLMTraffic]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\System\Currentcontrolset\Control\Lsa\Msv1_0')) {
    New-Item -Path 'HKLM:\System\Currentcontrolset\Control\Lsa\Msv1_0' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\System\Currentcontrolset\Control\Lsa\Msv1_0' -Name 'AuditReceivingNTLMTraffic' -Value 2 -PropertyType DWord -Force | Out-Null
exit 0
